/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const events = api.data.fetch_custom_events.output ? api.data.fetch_custom_events.output : [];
  return events.map(event => ({
    id: event,
    label: event
  }));
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const defaultSelectedItem = api.data.event_locale_get_list.output 
    ? api.data.event_locale_get_list.output.select_an_event 
    : '';
	return api.state.selectedEvent || (api.data.fetch_custom_events.output && api.data.fetch_custom_events.output[0] ? api.data.fetch_custom_events.output[0] : defaultSelectedItem);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const eventName = api.state.selectedEvent || (api.data.fetch_custom_events.output && api.data.fetch_custom_events.output[0] ? api.data.fetch_custom_events.output[0] : '');
  if (eventName)
      return `"${eventName}" Occurrences`;
  return '';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  // The the chart view has been changed (pie, line, etc), the config will be modified and stored locally (client state), 
  // otherwise, the initial data will be from the data broker 
	return api.state.eventProperties && api.state.eventProperties.length 
        ? api.state.eventProperties 
        : api.data.get_custom_event_properties.transformEventProperties;
}
